import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';

const DATA_URL = new URL('../data/books.json', import.meta.url);
const DATA_DIR_URL = new URL('../data/', import.meta.url);

async function ensureFile() {
  try {
    await readFile(DATA_URL);
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
    await mkdir(DATA_DIR_URL, { recursive: true });
    await writeFile(DATA_URL, '[]\n');
  }
}

export async function readBooks() {
  await ensureFile();
  const raw = await readFile(DATA_URL, 'utf8');
  return raw.trim() ? JSON.parse(raw) : [];
}

async function writeBooks(books) {
  await writeFile(DATA_URL, JSON.stringify(books, null, 2) + '\n');
}

export async function addBook({ title, author, notes }) {
  const books = await readBooks();
  const book = {
    id: randomUUID(),
    title,
    author,
    notes: notes || '',
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeBooks(books);
  return book;
}

export async function getBook(id) {
  const books = await readBooks();
  return books.find((b) => b.id === id) || null;
}

export async function markFinished(id) {
  const books = await readBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  await writeBooks(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await readBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = notes;
  await writeBooks(books);
  return book;
}

