import express from 'express';
import { readBooks, addBook, getBook, markFinished, updateNotes } from './lib/store.js';
import { renderHome, renderBook, renderNotFound } from './lib/views.js';

const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.urlencoded({ extended: false }));
app.use(express.static('public'));

app.get('/', async (req, res) => {
  const books = await readBooks();
  const reading = books.filter((b) => b.status === 'reading').reverse();
  const finished = books.filter((b) => b.status === 'finished').reverse();
  res.send(renderHome({ reading, finished }));
});

app.post('/books', async (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !author) return res.status(400).send('Title and author are required.');
  await addBook({ title, author, notes });
