  const book = await markFinished(req.params.id);
  if (!book) return res.status(404).send(renderNotFound());
  res.redirect(req.get('Referer') || '/');
});

app.post('/books/:id/notes', async (req, res) => {
  const book = await updateNotes(req.params.id, req.body.notes || '');
  if (!book) return res.status(404).send(renderNotFound());
