:root {
  color-scheme: light dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

body {
  max-width: 640px;
  margin: 0 auto;
  padding: 0 1.25rem 3rem;
  line-height: 1.5;
}

header {
  padding: 1.5rem 0 1rem;
}

.brand {
  font-size: 1.25rem;
  font-weight: 700;
  text-decoration: none;
  color: inherit;
}

h1, h2 {
  line-height: 1.2;
}

h2 {
  font-size: 1.05rem;
  margin: 2rem 0 0.75rem;
  color: #666;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

section.add-book {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 1rem 1.25rem;
}

section.add-book h2 {
  margin-top: 0;
}

form.add-form, form.notes-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.9rem;
}

input, textarea, button {
  font: inherit;
}

input[type="text"], textarea {
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 6px;
  resize: vertical;
}

button {
  align-self: flex-start;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 6px;
  background: #2563eb;
  color: white;
  cursor: pointer;
}

button:hover {
  background: #1d4ed8;
}

ul.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

li.book-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.75rem;
  border: 1px solid #eee;
  border-radius: 8px;
  flex-wrap: wrap;
}

.book-title {
  font-weight: 600;
  text-decoration: none;
  color: #111;
}

.book-title:hover {
  text-decoration: underline;
}

.book-author {
  color: #777;
  font-size: 0.9rem;
}

li.book-row .book-author {
  margin-right: auto;
}

.badge {
  font-size: 0.8rem;
  color: #16a34a;
  background: #dcfce7;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
}

.inline-form {
  margin: 0;
}

.inline-form button {
  padding: 0.35rem 0.75rem;
  font-size: 0.85rem;
  background: #f3f4f6;
  color: #111;
  border: 1px solid #ddd;
}

.inline-form button:hover {
  background: #e5e7eb;
}

.empty {
  color: #888;
  font-style: italic;
}

.back-link {
  display: inline-block;
  margin-bottom: 1rem;
  color: #2563eb;
  text-decoration: none;
}

.status {
  font-size: 0.85rem;
  font-weight: 600;
  display: inline-block;
  margin: 0.25rem 0 1rem;
}

.status.reading {
  color: #b45309;
}

.status.finished {
  color: #16a34a;
}

.share input {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 6px;
  color: #444;
  background: #fafafa;
}

